fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            let mut lines: Vec<String> = s.lines()
                .map(|line| {
                    if keepends {
                        format!("{}\n", line) // Retain line endings
                    } else {
                        line.to_string() // Do not retain line endings
                    }
                })
                .collect();

            // Ensure that each inner list is non-empty
            if lines.is_empty() {
                lines.push(String::new()); // Add a placeholder if empty
            }

            lines
        })
        .collect()
}